**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <cmath>
#include <climits>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();
    int K = 14;

    // Sumy prefiksowe
    vector<long long> prefix(n + 1, 0);
    for (int i = 0; i < n; i++)
        prefix[i + 1] = prefix[i] + T[i];

    long long bestDist = LLONG_MAX;
    long long bestSum = 0;
    int bestStart = 0, bestEnd = 0;

    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            long long suma = prefix[j + 1] - prefix[i];
            long long dist = abs(suma - K);
            if (dist < bestDist ||
                (dist == bestDist && i < bestStart) ||
                (dist == bestDist && i == bestStart && j - i < bestEnd - bestStart)) {
                bestDist = dist;
                bestSum = suma;
                bestStart = i;
                bestEnd = j;
            }
        }
    }

    int dl = bestEnd - bestStart + 1;
    cout << "a) Suma: " << bestSum << ", roznica od K: " << bestDist << endl;
    cout << "b) Pozycja poczatkowa: " << bestStart + 1
         << ", koncowa: " << bestEnd + 1
         << ", dlugosc: " << dl << endl;
    cout << "c) Elementy:";
    for (int i = bestStart; i <= bestEnd; i++)
        cout << " " << T[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Sumy prefiksowe daja O(1) obliczanie sumy kazdego podciagu. Sprawdzamy wszystkie O(n^2) podciagi, szukajac tego o sumie najblizszej K.

